------------ import ------------
local KTool = CS.Engine.Lib.KTool
local LuaBehaviour = CS.Engine.Modules.LuaBehaviour
local cs_coroutine = require("XLua.cs_coroutine")
local Yielders = CS.Engine.Lib.Yielders
local UIBattlingCtrlMgr = import("Game.UI.UIBattling.UIBattlingCtrlMgr")
------------ import ------------

------------ define ------------
local RootAnimationList = {
    Open = "Open",
    Close = "Close",
}
------------ define ------------

---@class TrainFieldBattleData
---@field RootAnimator                  	UnityEngine.Animator
---@field ImgBgTitle                    	Game.Native.Common.UISwitchImage
---@field ImgBgContent                  	Engine.Modules.LuaBehaviour
---@field LayoutContent                 	UnityEngine.RectTransform
---@field BtnShowInfo                   	UnityEngine.RectTransform
local TrainFieldBattleData = Class('TrainFieldBattleData')

------------ LifeCycle ------------

function TrainFieldBattleData:__init()
    self:CleanField()
end

function TrainFieldBattleData:__delete()
    self:CleanField()
end

function TrainFieldBattleData:Awake()
    self.numHealPreRound = 0
    self.numDamagePreRound = 0
    
    SetButtonAction(self.BtnShowInfo.gameObject, Bind(self, self.ShowShowInfoNodes))
    SetButtonAction(self.LayoutContent.gameObject, function()
        if self.boolIsShowInfo and isNull(self.coShowInfoNodes) then
            self.boolIsShowInfo = false
            self:RefreshTitleStatus()
            self:PlayRootAnimation(RootAnimationList.Close)
        end
    end)
end

function TrainFieldBattleData:Start()
    self:AddListener()
end

function TrainFieldBattleData:OnDestroy()
    self:RemoveListener()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

------------ LifeCycle ------------

function TrainFieldBattleData:CleanField()
    self.listDataNode = nil
    self.boolIsShowInfo = nil
    self.eventUpdateTrainFieldData = nil
    self.eventRoundChange = nil
    self.coShowInfoNodes = nil
    
    self.numHealPreRound = nil
    self.numDamagePreRound = nil
end

function TrainFieldBattleData:AddListener()
    self.eventRoundChange = Events.AddListener(Constants.EventNames.BattleRequireInput, Bind(self, self.UpdateValueRequireInput))
    self.eventUpdateTrainFieldData = Events.AddListener(Constants.EventNames.BattleDamageShow, Bind(self, self.UpdateTrainFieldSavedValue))
end

function TrainFieldBattleData:RemoveListener()
    Events.RemoveListener(Constants.EventNames.BattleRequireInput, self.eventRoundChange)
    Events.RemoveListener(Constants.EventNames.BattleDamageShow, self.eventUpdateTrainFieldData)
end

function TrainFieldBattleData:InitDataNode()
    self.listDataNode = {}
    local questId = UIBattlingDataMgr.questId
    local questVo = QuestConfMgr:GetQuestVoById(checkNumber(questId))
    local group = checkNumber(questVo.group)
    local dataType = UIBattleTrainFieldMgr.BATTLE_DATA_TYPE[group]
    for i = 1, #dataType do
        local nodeInfo = KTool.Instantiate(self.LayoutContent.gameObject, self.ImgBgContent.gameObject)
        if not IsNull(nodeInfo) then
            KTool.SetActive(nodeInfo, true)
            local lbNode = KTool.GetComponent(nodeInfo, typeof(LuaBehaviour))
            if not IsNull(lbNode) then
                lbNode:Init()
                local ltNode = lbNode.Env
                ltNode:InitNode(dataType[i])
                ltNode:UpdateNodeValue(0)
                table.insert(self.listDataNode, ltNode)
            end
        end
    end
    
    cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))
        self:ShowShowInfoNodes()
        self.boolIsShowInfo = true
    end)
end

function TrainFieldBattleData:RefreshTitleStatus()
    self.ImgBgTitle.Status = self.boolIsShowInfo and 1 or 2
end

---UpdateValueRoundStart
---1.单回合最高伤害，2.单回合最高治疗量
function TrainFieldBattleData:UpdateValueRequireInput()
    local valueRounds = UIBattlingCtrlMgr:GetInstance():GetPlayerTeamRoundsNum()
    local roundEx = valueRounds - 1
    if checkNumber(roundEx) < 1 then return end
    UIBattleTrainFieldMgr.numDamageRoundPre = checkNumber(UIBattleTrainFieldMgr.numDamageTotal / roundEx)
    if checkNumber(UIBattleTrainFieldMgr.numHealRoundMax) <= self.numHealPreRound then
        UIBattleTrainFieldMgr.numHealRoundMax = self.numHealPreRound
    end
    if checkNumber(UIBattleTrainFieldMgr.numDamageRoundMax) <= self.numDamagePreRound then
        UIBattleTrainFieldMgr.numDamageRoundMax = self.numDamagePreRound
    end
    for i, node in pairs(self.listDataNode) do
       self:UpdateDataNodeValue(node)
    end
    self.numHealPreRound = 0
    self.numDamagePreRound = 0

end

function TrainFieldBattleData:UpdateDataNodeValue(node)
    local value2Show
    ---刷新回合最高伤害
    if node.dataType == Constants.TYPE_DATA_TRAIN_FIELD.DAMAGE_MAX_ROUND then
        value2Show = UIBattleTrainFieldMgr.numDamageRoundMax
    ---刷新回合最高治疗
    elseif node.dataType == Constants.TYPE_DATA_TRAIN_FIELD.HEAL_MAX_ROUND then
        value2Show = UIBattleTrainFieldMgr.numHealRoundMax
    ---刷新平均伤害    
    elseif node.dataType == Constants.TYPE_DATA_TRAIN_FIELD.DAMAGE_PRE_ROUND then
        value2Show = UIBattleTrainFieldMgr.numDamageRoundPre
    end
    if value2Show then
        node:UpdateNodeValue(value2Show)
    end
end

function TrainFieldBattleData:UpdateTotalDamageValue()
    for i, node in pairs(self.listDataNode) do
        if node.dataType == Constants.TYPE_DATA_TRAIN_FIELD.DAMAGE_TOTAL then
            node:UpdateNodeValue(UIBattleTrainFieldMgr.numDamageTotal)
        end
    end
end

function TrainFieldBattleData:UpdateTrainFieldSavedValue(data)
    local roleCamp = UIBattlingDataMgr:GetRoleCampByRoleId(data.roleId)
    --if checkBool(data.isDot) then return end
    if data.damageType == Constants.DamageType.Heal then -- 治疗类型
        local valueHealNow = checkInt(math.abs(data.damage))
        self.numHealPreRound = checkInt(self.numHealPreRound) + valueHealNow
        --if checkNumber(UIBattleTrainFieldMgr.numHealRoundMax) <= valueHealNow then
        --    UIBattleTrainFieldMgr.numHealRoundMax = valueHealNow
        --end
    else -- 伤害类型
        if BattleInfo:IsUserCamp(roleCamp) then return end -- 目标为非敌方阵营的伤害不计入
        --- 单次最高伤害
        local valueDamageNow = checkInt(math.abs(data.damage))
        self.numDamagePreRound = checkInt(self.numDamagePreRound) + valueDamageNow
        --if checkNumber(UIBattleTrainFieldMgr.numDamageRoundMax) <= valueDamageNow then
        --    UIBattleTrainFieldMgr.numDamageRoundMax = valueDamageNow
        --end
        --- 总伤害
        UIBattleTrainFieldMgr.numDamageTotal = UIBattleTrainFieldMgr.numDamageTotal + valueDamageNow
        --- 刷新总伤害统计
        self:UpdateTotalDamageValue()
    end
end

function TrainFieldBattleData:ShowShowInfoNodes()
    if self.coShowInfoNodes or self.boolIsShowInfo then return end
    self.coShowInfoNodes = cs_coroutine.start(function()
        self:PlayRootAnimation(RootAnimationList.Open)
        --for i, node in ipairs(self.listDataNode) do
        --    node:AnimationWait()
        --end
        --for i, node in ipairs(self.listDataNode) do
        --    node:ShowNode()
        --    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
        --end
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
        self.coShowInfoNodes = nil
        self.boolIsShowInfo = true
        self:RefreshTitleStatus()
    end)
end

function TrainFieldBattleData:PlayRootAnimation(name)
    if not isNull(self.RootAnimator) then
        self.RootAnimator:Play(name)
    end
end

return TrainFieldBattleData

